public record VisualLayer (
    string Id, 
    VisualContent Content, 
    long TrackIndex, 
    long RenderIndex, 
    bool IsMainTrack, 
    TimeRange Target, 
    TimeMap TimeMap, 
    Crop Crop, 
    Clip Clip, 
    bool UniformScale, 
    Dictionary<LayerProperty, KeyframeTrack> Keyframes, 
    CanvasMaterial? Canvas, 
    Cutout? Cutout, 
    ColorFilter[] Filters, 
    bool ToneMapsHdr, 
    ChromaKey? ChromaKey, 
    bool RetouchesSkin, 
    bool EnhancesQuality, 
    VideoEffect[] Effects, 
    LayerTransition? TransitionOut, 
    ClipMask[] Masks, 
    ClipAnimation[] Animations, 
    BlendMode? BlendMode, 
    long Stabilization
) : IDisposable {
    public void Dispose() {
    FFIObjectUtil.DisposeAll(
            this.Id,
            this.Content,
            this.TrackIndex,
            this.RenderIndex,
            this.IsMainTrack,
            this.Target,
            this.TimeMap,
            this.Crop,
            this.Clip,
            this.UniformScale,
            this.Keyframes,
            this.Canvas,
            this.Cutout,
            this.Filters,
            this.ToneMapsHdr,
            this.ChromaKey,
            this.RetouchesSkin,
            this.EnhancesQuality,
            this.Effects,
            this.TransitionOut,
            this.Masks,
            this.Animations,
            this.BlendMode,
            this.Stabilization);
    }
}

