/// <summary>
/// One language of generated voice-over, added to a draft as an audio track.
/// </summary>
/// <param name="Path">
/// The spoken track as one file aligned to the timeline (file time 0 = timeline start).
/// </param>
/// <param name="FileDuration">
/// Length of the file, seconds.
/// </param>
/// <param name="Lines">
/// Where each line was placed; every line becomes its own clip on the track.
/// </param>
/// <param name="IsAudible">
/// Muted tracks can be unmuted in CapCut with the track's speaker button.
/// </param>
/// <param name="IsBackground">
/// The project's sound without its voice, played while the original is muted under the voice-over
/// (`OriginalAudio.Replace`); `lines` are the stretches it covers.
/// </param>
public record VoiceOverTrack (
    string Language, 
    /// <summary>
    /// The spoken track as one file aligned to the timeline (file time 0 = timeline start).
    /// </summary>
    string Path, 
    /// <summary>
    /// Length of the file, seconds.
    /// </summary>
    double FileDuration, 
    /// <summary>
    /// Where each line was placed; every line becomes its own clip on the track.
    /// </summary>
    LineRange[] Lines, 
    /// <summary>
    /// Muted tracks can be unmuted in CapCut with the track's speaker button.
    /// </summary>
    bool IsAudible, 
    /// <summary>
    /// The project's sound without its voice, played while the original is muted under the voice-over
    /// (`OriginalAudio.Replace`); `lines` are the stretches it covers.
    /// </summary>
    bool IsBackground
) {
}

class FfiConverterTypeVoiceOverTrack: FfiConverterRustBuffer<VoiceOverTrack> {
    public static FfiConverterTypeVoiceOverTrack INSTANCE = new FfiConverterTypeVoiceOverTrack();

    public override VoiceOverTrack Read(BigEndianStream stream) {
        return new VoiceOverTrack(
            Language: FfiConverterString.INSTANCE.Read(stream),
            Path: FfiConverterString.INSTANCE.Read(stream),
            FileDuration: FfiConverterDouble.INSTANCE.Read(stream),
            Lines: FfiConverterSequenceTypeLineRange.INSTANCE.Read(stream),
            IsAudible: FfiConverterBoolean.INSTANCE.Read(stream),
            IsBackground: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(VoiceOverTrack value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Language)
            + FfiConverterString.INSTANCE.AllocationSize(value.Path)
            + FfiConverterDouble.INSTANCE.AllocationSize(value.FileDuration)
            + FfiConverterSequenceTypeLineRange.INSTANCE.AllocationSize(value.Lines)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.IsAudible)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.IsBackground);
    }

    public override void Write(VoiceOverTrack value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Language, stream);
            FfiConverterString.INSTANCE.Write(value.Path, stream);
            FfiConverterDouble.INSTANCE.Write(value.FileDuration, stream);
            FfiConverterSequenceTypeLineRange.INSTANCE.Write(value.Lines, stream);
            FfiConverterBoolean.INSTANCE.Write(value.IsAudible, stream);
            FfiConverterBoolean.INSTANCE.Write(value.IsBackground, stream);
