public enum BlendMode: int {
    Normal,
    Screen,
    Darken,
    Lighten,
    Overlay,
    HardLight,
    SoftLight,
    LinearBurn,
    ColorBurn,
    ColorDodge,
    Multiply
}

class FfiConverterTypeBlendMode: FfiConverterRustBuffer<BlendMode> {
    public static FfiConverterTypeBlendMode INSTANCE = new FfiConverterTypeBlendMode();

    public override BlendMode Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return BlendMode.Normal;
            case 2: return BlendMode.Screen;
            case 3: return BlendMode.Darken;
            case 4: return BlendMode.Lighten;
            case 5: return BlendMode.Overlay;
            case 6: return BlendMode.HardLight;
            case 7: return BlendMode.SoftLight;
            case 8: return BlendMode.LinearBurn;
            case 9: return BlendMode.ColorBurn;
            case 10: return BlendMode.ColorDodge;
            case 11: return BlendMode.Multiply;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeBlendMode.Read()", value));
        }
    }

    public override int AllocationSize(BlendMode value) {
        return 4;
    }

    public override void Write(BlendMode value, BigEndianStream stream) {
        switch (value) {
            case BlendMode.Normal: stream.WriteInt(1); break;
            case BlendMode.Screen: stream.WriteInt(2); break;
            case BlendMode.Darken: stream.WriteInt(3); break;
            case BlendMode.Lighten: stream.WriteInt(4); break;
            case BlendMode.Overlay: stream.WriteInt(5); break;
            case BlendMode.HardLight: stream.WriteInt(6); break;
            case BlendMode.SoftLight: stream.WriteInt(7); break;
            case BlendMode.LinearBurn: stream.WriteInt(8); break;
            case BlendMode.ColorBurn: stream.WriteInt(9); break;
            case BlendMode.ColorDodge: stream.WriteInt(10); break;
            case BlendMode.Multiply: stream.WriteInt(11); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeBlendMode.Write()", value));
        }
    }
}







