/// <summary>
/// Every failure, flat on the other side: each case carries its localized text as `message` (Swift
/// `CoreError.ProjectOpen(message:)`, C# `CoreException.ProjectOpen` with `.Message`), design decision 4.
/// </summary>
public class CoreException: UniffiException {
    CoreException(string message): base(message) {}

    // Each variant is a nested class
    // Flat enums carries a string error message, so no special implementation is necessary.
    
    /// <summary>
    /// The project is open in CapCut, which would overwrite our changes when it saves.
    /// </summary>
    public class ProjectOpen: CoreException {
        public ProjectOpen(string message): base(message) {}
    }
    
    /// <summary>
    /// The project keeps a single timeline (an older CapCut), so a dubbed timeline can't be added.
    /// </summary>
    public class NoTimelineList: CoreException {
        public NoTimelineList(string message): base(message) {}
    }
    
    /// <summary>
    /// No such project or timeline (the `ecc info` arguments).
    /// </summary>
    public class NotFound: CoreException {
        public NotFound(string message): base(message) {}
    }
    
    /// <summary>
    /// A draft that can't be read or parsed.
    /// </summary>
    public class Unreadable: CoreException {
        public Unreadable(string message): base(message) {}
    }
    
    /// <summary>
    /// A draft whose JSON is broken or lacks what a writer needs.
    /// </summary>
    public class Malformed: CoreException {
        public Malformed(string message): base(message) {}
    }
    
    public class Io: CoreException {
        public Io(string message): base(message) {}
    }
    
    /// <summary>
    /// A Rust panic caught at the boundary, with its message.
    /// </summary>
    public class Internal: CoreException {
        public Internal(string message): base(message) {}
    }
    
}

class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return new CoreException.ProjectOpen(FfiConverterString.INSTANCE.Read(stream));
            case 2: return new CoreException.NoTimelineList(FfiConverterString.INSTANCE.Read(stream));
            case 3: return new CoreException.NotFound(FfiConverterString.INSTANCE.Read(stream));
            case 4: return new CoreException.Unreadable(FfiConverterString.INSTANCE.Read(stream));
            case 5: return new CoreException.Malformed(FfiConverterString.INSTANCE.Read(stream));
            case 6: return new CoreException.Io(FfiConverterString.INSTANCE.Read(stream));
            case 7: return new CoreException.Internal(FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Read()", value));
        }
    }

    public override int AllocationSize(CoreException value) {
        return 4 + FfiConverterString.INSTANCE.AllocationSize(value.Message);
    }

    public override void Write(CoreException value, BigEndianStream stream) {
        switch (value) {
            case CoreException.ProjectOpen:
                stream.WriteInt(1);
                break;
            case CoreException.NoTimelineList:
                stream.WriteInt(2);
                break;
            case CoreException.NotFound:
                stream.WriteInt(3);
                break;
            case CoreException.Unreadable:
                stream.WriteInt(4);
                break;
            case CoreException.Malformed:
                stream.WriteInt(5);
                break;
            case CoreException.Io:
                stream.WriteInt(6);
                break;
            case CoreException.Internal:
                stream.WriteInt(7);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Write()", value));
        }
    }
}





