/// <summary>
/// What a visual layer shows. Compound clips hold their inner timeline as another `Timeline` object.
/// </summary>
public record VisualContent: IDisposable  {
    
    public record Video (
        string Path
    ) : VisualContent {}
    
    public record Photo (
        string Path
    ) : VisualContent {}
    
    public record Text (
        TextLayerSpec Spec
    ) : VisualContent {}
    
    public record Compound (
        Timeline Timeline
    ) : VisualContent {}
    
    public record Sticker (
        StickerSpec Spec
    ) : VisualContent {}
    

    
    public void Dispose() {
        switch (this) {
            case VisualContent.Video variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.Path);
                break;
            case VisualContent.Photo variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.Path);
                break;
            case VisualContent.Text variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.Spec);
                break;
            case VisualContent.Compound variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.Timeline);
                break;
            case VisualContent.Sticker variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.Spec);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in VisualContent.Dispose()", this));
        }
    }
    
}

